package com.mcnex.conversation;
import android.media.*;import java.io.*;
final class PhoneMicrophone implements AutoCloseable {
 private final NativeKoreanSpeech speech;private AudioRecord record;private Thread worker;private volatile boolean stopping;volatile String error="";volatile long samplesRead;
 PhoneMicrophone(NativeKoreanSpeech speech)throws Exception{this.speech=speech;int min=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(min<=0)throw new IOException("휴대폰 마이크 형식을 지원하지 않습니다");record=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.max(min*2,6400));if(record.getState()!=AudioRecord.STATE_INITIALIZED){record.release();throw new IOException("휴대폰 마이크를 열 수 없습니다");}record.startRecording();if(record.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING){record.release();throw new IOException("다른 앱의 마이크 사용을 확인하세요");}worker=new Thread(()->{short[] pcm=new short[1600];try{while(!stopping){int n=record.read(pcm,0,pcm.length,AudioRecord.READ_BLOCKING);if(stopping)break;if(n<0)throw new IOException("휴대폰 마이크 오류 "+n);if(n==0)continue;float[] samples=new float[n];for(int i=0;i<n;i++)samples[i]=pcm[i]/32768f;speech.accept(samples);samplesRead+=n;}}catch(Exception e){if(!stopping)error=e.getMessage();}finally{stopping=true;speech.finish();try{record.stop();}catch(Exception ignored){}}},"phone-microphone-pcm");worker.start();}
 boolean recording(){return !stopping&&worker!=null&&worker.isAlive();}
 public void close(){stopping=true;try{record.stop();}catch(Exception ignored){}speech.finish();if(worker!=null&&worker!=Thread.currentThread())try{worker.join(1500);}catch(InterruptedException e){Thread.currentThread().interrupt();}if(worker==null||!worker.isAlive())record.release();}
}
